/* Minimal interface copy; icons retain accessible names and tooltips. */
const cleanPaths={camera:'M14 4l2 3h4v13H4V7h4l2-3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M3 3h18v18H3z M3 17l6-6 5 5 3-3 4 4 M8 7h.01',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',edit:'M16 3l5 5-12 12-6 1 1-6z M14 5l5 5',flag:'M5 21V3 M5 3c5-4 9 4 14 0v11c-5 4-9-4-14 0',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',library:'M4 4h5v16H4z M12 4h3v16h-3 M18 3l4 16',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L20 5',close:'M6 6l12 12 M18 6L6 18',play:'M7 4l14 8-14 8z',barcode:'M3 7V3h4 M17 3h4v4 M21 17v4h-4 M7 21H3v-4 M7 7v10 M10 7v10 M14 7v10 M17 7v10',back:'M19 12H5 M11 6l-6 6 6 6',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-2l2 2 M18 17a7 7 0 0 1-12 2l-2-2'};
function cleanIcon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${cleanPaths[name]||cleanPaths.plus}"/></svg>`}
const cleanButtons={Search:['search','Search'],Favorites:['heart','Favorites'],Favourites:['heart','Favorites'],'Manage catalogue':['library','Catalogue'],Edit:['edit','Edit'],'Report an error':['flag','Report error'],Remove:['trash','Remove'],'Take photo':['camera','Take photo'],'Choose images':['image','Choose images'],'Clear filters':['close','Clear filters'],'Scan':['barcode','Scan barcode'],'▥ Scan':['barcode','Scan barcode'],'♡':['heart','Favorites'],'♥':['heart','Favorites'],'Scan a photo':['image','Scan photo']};
const cleanCopy={'＋ Add Exercise':'Exercise','＋ Add Exercise from Catalog':'Exercise','＋ Add Set':'Set','＋ Add set':'Set','＋ Create Routine':'Routine','＋ Create New Routine':'Routine','＋ Create custom exercise':'Custom','＋ Enter nutrition label':'New food','Start Workout →':'Start','Start Workout':'Start','Start Empty Workout':'Workout','Finish & save session':'Finish','Manage account':'Account','Download backup ↓':'Export','Import from Hevy ↗':'Hevy','Choose file ↑':'Import','Show more exercises':'More','Browse all foods →':'Browse','Publish food & choose portion':'Publish','Save changes & choose portion':'Save','Publish exercise':'Publish','Save changes':'Save','Save routine':'Save','Create routine':'Routine','Edit routine':'Routine','Create shared exercise':'Exercise','Edit shared exercise':'Exercise','Send report to creator':'Send','Review report':'Review','Save review':'Save','Back to catalogue':'Catalogue','Publish to shared catalogue':'Share','Remove favorite':'Unfavorite','Add to favorites':'Favorite','Shared catalogue':'Catalogue','Product photos':'Photos','Your product photos':'Photos','Find your next exercise':'Exercises','Enter the nutrition label':'Food','Nutrition label':'Label','Data & backups':'Data','Session history':'History','Workout details':'Details','Error reports':'Reports','Track as':'Tracking','Demonstration image URL (optional, HTTPS)':'Image URL','Instructions · one step per line':'Instructions','What should be corrected?':'Correction','Response to reporter':'Response','Recently added':'Recent'};
function cleanChrome(root=document){root.querySelectorAll('button').forEach(b=>{if(b.dataset.clean)return;let text=b.textContent.replace(/\s+/g,' ').trim(),icon=cleanButtons[text];if(icon){b.setAttribute('aria-label',icon[1]);b.title=icon[1];b.innerHTML=cleanIcon(icon[0]);b.classList.add('symbol-button');b.dataset.clean='1';return}let label=cleanCopy[text];if(label){b.setAttribute('aria-label',b.getAttribute('aria-label')||text);if(/^＋/.test(text)){b.innerHTML=cleanIcon('plus')+'<span>'+label+'</span>';b.classList.add('short-button')}else b.textContent=label;b.dataset.clean='1'}});
 root.querySelectorAll('h2,h3,label,summary').forEach(el=>{if(el.children.length)return;let text=el.textContent.trim();if(cleanCopy[text])el.textContent=cleanCopy[text]});
 root.querySelectorAll('p').forEach(p=>{if(p.matches('[role="status"],.auth-error')||p.querySelector('a,input,button'))return;let t=p.textContent.trim();if(/^(Search once\.|Choose exercises,|Find a food,|\d{1,2} \w+.*Find a food|Calculated from the entered|Copy the values|Use one reference basis|Add the nutrition label|Contribute foods and exercises|Reports on your contributions|Update the catalogue entry separately|Use an image you have permission)/.test(t))p.remove()});
 root.querySelectorAll('.section-note').forEach(el=>{let t=el.textContent.trim();if(/^(Saved products are shared|Visible to all signed-in)/.test(t))el.textContent='Shared · Creator edits only'});
 root.querySelectorAll('.subtitle:empty,.auth-footnote').forEach(el=>el.remove());
}
const cleanOldTitle=title;title=function(section,t,sub,action=''){return cleanOldTitle('',section,'',action)};
const cleanOldModal=modal;modal=function(html){cleanOldModal(html);cleanChrome($('#modal-content'))};
const cleanOldRender=render;render=function(){cleanOldRender();cleanChrome(document)};
// Deferred result lists and dynamically inserted buttons use the same design system.
let cleanQueued=false;new MutationObserver(()=>{if(cleanQueued)return;cleanQueued=true;queueMicrotask(()=>{cleanQueued=false;cleanChrome(document)})}).observe(document.body,{subtree:true,childList:true});
barcodePreview=function(){stopBarcodeCamera();modal(modalHead('Scan')+`<div class="barcode-camera"><video id="barcode-video" muted playsinline></video><div class="barcode-guide" aria-hidden="true"></div></div><p id="camera-status" class="small-muted" role="status"></p><div class="scanner-alternatives"><button type="button" class="icon-btn" aria-label="Scan barcode photo" title="Scan photo" onclick="document.getElementById('barcode-photo').click()">${cleanIcon('image')}</button></div><input type="file" id="barcode-photo" accept="image/*" hidden onchange="scanBarcodePhoto(this.files[0]);this.value=''"><details id="barcode-manual" class="compact-details"><summary onclick="stopBarcodeCamera()">Barcode</summary><form onsubmit="stopBarcodeCamera();lookupLocalBarcode(event)"><div class="manual-barcode-row"><input id="barcode-value" required aria-label="Barcode" inputmode="numeric" pattern="[0-9]{8,14}" maxlength="14" placeholder="Barcode"><button class="btn symbol-button" aria-label="Find product" title="Find">${cleanIcon('search')}</button></div></form></details><div id="barcode-status" role="status"></div>`);$('#modal').classList.add('catalog-modal');startBarcodeCamera()};
cameraMessage=function(text){let node=$('#camera-status');if(!node)return;const condensed=text.includes('denied')?'Camera blocked. Use photo or barcode.':text.includes('No camera')?'No camera. Use photo or barcode.':text.includes('unavailable')||text.includes('failed to load')?'Camera unavailable. Use photo or barcode.':text.includes('Could not start')?'Camera unavailable. Use photo or barcode.':text.includes('No product barcode')?'Not detected. Try another photo.':text.includes('smaller than')?'Maximum 20 MB.':text.includes('Allow camera')?'Camera permission required.':text.includes('Reading barcode')?'Reading…':text.includes('Barcode found')?'Found':text.includes('Point the camera')?'':text;node.textContent=condensed;if(/blocked|unavailable|No camera/.test(condensed)){let details=$('#barcode-manual');if(details)details.open=true}};
const cleanPhotoControls=photoControls;photoControls=function(){return cleanPhotoControls().replace('<h3>Product photos</h3>','<h3>Photos</h3>').replace('Add the nutrition label or packaging. Photos stay private to your account. Enter nutrition values below.','Private · Nutrition entered manually.').replace('Up to four photos. Saved with the product.','4 photos max.')};
cleanChrome(document);
